import { z } from "zod";

export const mailboxSchema = z
    .object({
        id: z.uuid(),
        domainId: z.uuid(),
        localPart: z.string(),
        address: z.string(),
        displayName: z.string(),
        signatureHtml: z.string().nullable(),
        createdAt: z.iso.datetime(),
        deletedAt: z.iso.datetime().nullable(),
    })
    .meta({ id: "Mailbox" });

export const createMailboxSchema = z
    .object({
        /** Generated by the app, so the mailbox it shows before the request lands is the one the server creates. */
        id: z.uuid(),
        domainId: z.uuid(),
        localPart: z
            .string()
            .trim()
            .toLowerCase()
            .regex(/^[a-z0-9](?:[a-z0-9._+-]{0,62}[a-z0-9])?$/, "Use letters, numbers, dots, dashes or plus signs."),
        displayName: z.string().trim().min(1, "Add a name people will see.").max(200),
    })
    .meta({ id: "CreateMailbox" });

export const updateMailboxSchema = z
    .object({
        displayName: z.string().trim().min(1, "Add a name people will see.").max(200).optional(),
        signatureHtml: z.string().max(20_000).nullable().optional(),
    })
    .meta({ id: "UpdateMailbox" });

export type Mailbox = z.infer<typeof mailboxSchema>;
export type CreateMailboxInput = z.infer<typeof createMailboxSchema>;
export type UpdateMailboxInput = z.infer<typeof updateMailboxSchema>;
